// Gerion et al., J. Phys. Chem. B 2001, DOI 10.1021/jp0105488.
// Explanatory apparatus geometry. All quantitative conditions come from the selected canonical operation.
const C={ink:'#173848',line:'#6c91a4',fluid:'#c9e8eb',green:'#247e74',hot:'#c1874b',pale:'#f2f7fa',solid:'#dfbd79'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const text=(x,y,s,size=16)=>`<text x="${x}" y="${y}" text-anchor="middle" font-family="Arial,sans-serif" font-size="${size}">${esc(s)}</text>`;
const path=(d,c=C.line,w=2)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const box=(x,y,w,h,fill=C.pale)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="9" fill="${fill}" stroke="${C.line}" stroke-width="2"/>`;
const arrow=(x,y,a=0)=>`<g transform="translate(${x} ${y}) rotate(${a})">${path('M-20 0H13',C.green,2.5)}<path d="M10 -6L20 0L10 6Z" fill="${C.green}"/></g>`;
function lines(s,n=73){let rows=[],row='';for(const w of String(s).split(/\s+/)){if((row+' '+w).trim().length>n&&row){rows.push(row);row=w;}else row=(row+' '+w).trim();}if(row)rows.push(row);return rows;}
const note=s=>lines(s).map((v,i)=>text(300,343+i*18,v,13)).join('');
const title=s=>text(300,29,s,20);
function vial(x,y,{pellet=false,dry=false}={}){return path(`M${x-32} ${y-62}V${y+41}Q${x} ${y+57} ${x+32} ${y+41}V${y-62}Z`,C.line,2.5)+(!dry?`<path d="M${x-28} ${y-3}H${x+28}V${y+38}Q${x} ${y+52} ${x-28} ${y+38}Z" fill="${C.fluid}"/>`:'')+(pellet?`<path d="M${x-26} ${y+34}Q${x} ${y+25} ${x+26} ${y+34}V${y+39}Q${x} ${y+48} ${x-26} ${y+39}Z" fill="${C.solid}"/>`:'');}
function drawFlask(x=250,y=180,{heated=false,stir=false,nitrogen=false,layer=0}={}){let s=`<g transform="translate(${x} ${y})">`+path('M-17 -83H17V-48L44 -30L54 -59L72 -50L63 -19C97 29 70 91 0 91C-70 91 -97 29 -63 -19L-72 -50L-54 -59L-44 -30L-17 -48Z',C.line,2.5)+`<path d="M-73 28Q0 39 73 28C66 106 -66 106 -73 28Z" fill="${C.fluid}"/>`+path('M-60 10Q-74 49 -43 70','white',5);
 if(stir)s+=path('M-15 70H15',C.green,5)+path('M-29 64Q0 50 29 64',C.green,1.5);
 if(nitrogen)s+=text(-76,-96,'N₂',17)+path('M-74 -84V-57')+arrow(-64,-72,90);
 if(heated)s+=box(-104,108,208,36,'#f6e8d3')+text(0,132,'Heating · apparatus unspecified',12)+path('M-50 103Q-59 93 -50 83M0 103Q-9 93 0 83M50 103Q41 93 50 83',C.hot,2);
 s+='</g>';if(layer)s+=`<circle cx="477" cy="195" r="${25+layer*5}" fill="${C.pale}" stroke="${C.green}" stroke-width="${layer+2}" stroke-dasharray="4 3"/><circle cx="477" cy="195" r="19" fill="${C.solid}"/>`+text(477,259,layer===1?'Primed surface':'Siloxane-coated particle',14);return s;}
function labeled(x,y,label,opts={}){return vial(x,y,opts)+text(x,y+81,label,14);}
const panel=(x,y,w,rows)=>box(x,y,w,34+rows.length*28)+rows.map((s,i)=>text(x+w/2,y+28+i*28,s,15)).join('');
function addition(labels,{wet=false}={}){return labeled(128,186,wet?'Wet nanocrystals':'Dispersion',{pellet:wet})+arrow(243,184)+panel(301,94,250,labels)+arrow(427,226,90);}
function rotor(){return `<circle cx="153" cy="177" r="70" fill="${C.pale}" stroke="${C.line}" stroke-width="2"/>`+[0,60,120,180,240,300].map(a=>`<g transform="translate(153 177) rotate(${a})">${box(-9,-59,18,39,C.fluid)}</g>`).join('')+`<circle cx="153" cy="177" r="15" fill="${C.line}"/>`+text(153,276,'Centrifugation',17);}
function centrifuge(pellet){return rotor()+arrow(274,180)+labeled(377,178,pellet?'Retain pellet':'Retain supernatant',{pellet:true})+panel(452,97,133,pellet?['Discard','supernatant']:['Discard','sediment']);}
function dialysis(solvent){return box(57,88,260,208,'#eef5f9')+`<path d="M60 152H314V294H60Z" fill="${C.fluid}" opacity=".7"/>`+box(130,111,110,128,'#fff')+path('M129 112H241M129 239H241',C.green,5)+text(185,165,'Sample inside',14)+text(185,194,'Retained',14)+[145,171,197].map(y=>arrow(278,y)).join('')+panel(363,112,209,['External medium',solvent])+text(186,319,'Semipermeable membrane',14);}
function filter(o){const nylon=o.id==='filter045';return box(78,66,63,98,'#fff')+path('M92 66V46H127V66M109 164V184')+box(54,184,111,25,C.fluid)+path('M74 197H145',C.green,3)+arrow(110,218,90)+`<g transform="translate(110 255) scale(.7)">${vial(0,0)}</g>`+text(110,315,'Retain filtrate',14)+panel(238,113,322,[nylon?'Nylon syringe membrane':o.id==='filter022'?'Acetate membrane':'Water-branch filter',o.id==='optional-filter'?'Pore unit conflict preserved':'Reported pore size alongside']);}
function membraneConcentrate(){return box(81,69,131,217,'#fff')+path('M97 96H196L177 167H117Z')+`<path d="M107 125H186L177 161H116Z" fill="${C.fluid}"/>`+path('M117 168H177',C.green,4)+arrow(149,211,90)+panel(303,91,258,['Retain upper concentrate','Small silanes pass through'])+text(149,315,'Centrifugal membrane unit',14);}
function column(cleanup=false){return box(230,70,61,116,'#e1f0ec')+path('M234 110H287M234 170H287',C.green,3)+arrow(260,50,90)+path('M260 186V210')+arrow(260,219,90)+`<g transform="translate(260 239) scale(.78)">${vial(0,0)}</g>`+text(260,307,'Collected fraction',14)+panel(367,95,207,cleanup?['NAP size exclusion','Unbound species removed']:['Size exclusion','Collect fluorescent','fraction only']);}
function gel(o,r){const extract=o.id==='extract',load=o.id==='load',run=/run/.test(o.id);let s=box(75,98,265,191,'#d9ebed');for(let i=0;i<5;i++)s+=box(97+i*45,123,26,13,'#fff')+(extract&&i===2?box(97+i*45,211,26,17,'#d4bd72'):'');if(run)s+=arrow(355,199,90)+text(373,94,'−',22)+text(373,293,'+',22);s+=panel(414,113,165,extract?['Filter-paper','band recovery']:load?['Glycerol mixture','Load separately']:o.id==='detect'?['UV illumination','CCD imaging']:['Distinct samples','Separate lanes']);return s+note('Lane geometry is explanatory; no synthetic bands or measured fluorescence patterns are drawn. Refer to the original figure.');}
function grid(eels=false){return labeled(103,183,'Aliquot')+arrow(215,187)+`<circle cx="364" cy="187" r="65" fill="${C.pale}" stroke="${C.line}" stroke-width="3"/>`+[-40,-20,0,20,40].map(x=>path(`M${364+x} 134V240M311 ${187+x}H417`)).join('')+text(365,289,eels?'Carbon-coated grid':'Ultrathin carbon support',16);}
function mica(kind){let s=`<path d="M145 223L343 183L457 229L258 273Z" fill="#e5edf1" stroke="${C.line}" stroke-width="2"/>`+text(300,305,'Freshly cleaved mica',17);if(kind==='rinse')s+=text(294,91,'Water rinse',18)+arrow(297,138,90);else if(kind==='dry')s+=text(293,91,'Nitrogen flow',18)+arrow(244,137);else if(kind==='image')s+=path('M186 99H310L295 149H321L308 178',C.green,4)+text(398,116,'Tapping-mode probe',15);else s+=labeled(112,102,'Aliquot')+arrow(225,162,35);return s;}
function optical(label,paired=false){return box(47,90,177,158)+text(134,131,label,label.length>20?14:16)+text(134,184,'Instrument',14)+arrow(265,170)+box(327,132,47,100,C.fluid)+(paired?box(443,132,47,100,'#e8dced')+text(468,265,'Reference',14):'')+text(350,265,'Specimen',14);}
function precipitateStock(){return labeled(82,187,'Starting dispersion')+arrow(174,178)+panel(214,89,177,['Anhydrous methanol','Add antisolvent'])+arrow(423,178)+labeled(516,187,'Wet precipitate',{pellet:true});}
function aqueousDissolve(){return labeled(91,187,'Dried precipitate',{pellet:true,dry:true})+arrow(184,178)+panel(239,91,163,['Millipore water','Redisperse'])+arrow(429,178)+labeled(519,187,'Aqueous dispersion');}
function electronMicroscopy(eels=false){let s=box(100,61,119,58)+text(159,94,'Electron source',14)+path('M159 121V170',C.green,3)+arrow(159,149,90)+path('M110 187H211',C.line,6)+text(89,216,'Grid',15)+text(259,184,'Dried specimen',15)+path('M159 191V242',C.green,3);if(eels){s+=box(115,242,92,39)+text(161,267,'Analyzer',14)+path('M207 261H370',C.green,3)+arrow(312,261)+box(393,213,150,81)+text(468,242,'Energy-loss',17)+text(468,270,'detector',17)+text(420,118,'EELS acquisition',19);}else{s+=arrow(159,219,90)+box(95,259,128,40,'#e4f1ea')+text(159,286,'Image detector',14)+panel(350,118,206,['TEM acquisition','CCD or digitization']);}return s;}
function hplcStage(id){if(id==='inspect-fractions')return labeled(112,171,'Void fraction')+labeled(299,171,'Fluorescent fraction')+labeled(488,171,'Late fraction')+text(300,294,'Inspect each collected fraction separately',18);let s=box(238,91,56,165,'#dceceb')+text(264,289,'SEC column',16);if(id==='load'){s+=box(52,72,39,97,'#fff')+path('M61 72V52H83V72M71 170V188H205')+arrow(190,188)+text(100,236,'Sample aliquot',17)+panel(366,100,195,['Load the sample','Column geometry','is explanatory']);}else{s+=box(43,117,99,77)+text(92,163,'Eluent',17)+arrow(185,162)+arrow(341,162)+panel(395,113,172,['UV absorbance','Collect eluent']);}return s;}
function ellmanStage(id){if(id==='read')return optical('Absorbance difference',true);let s=labeled(157,185,'DTNB-treated aliquot')+labeled(439,185,'Matched blank');if(id==='prepare')s+=panel(211,73,151,['DTNB reagent'])+arrow(224,139,140)+text(434,100,'No DTNB',16);else s+=panel(217,76,160,['Room-temperature','incubation']);return s;}
function saltIncubation(){return labeled(122,181,'Silanized aliquots')+labeled(469,181,'MPA aliquots')+panel(230,77,154,['Separate salt','concentrations'])+text(299,293,'Incubate before loading the salt-free gel',18);}

function stockPreparation(rows){return panel(49,104,247,rows)+arrow(336,180)+labeled(465,186,'Prepared mixture');}
function dryGrid(eels){return `<circle cx="300" cy="203" r="65" fill="${C.pale}" stroke="${C.line}" stroke-width="3"/>`+[-40,-20,0,20,40].map(x=>path(`M${300+x} 150V256M247 ${203+x}H353`)).join('')+text(300,110,eels?'Dry overnight':'Dry in air',20)+text(300,305,eels?'Carbon-coated grid':'Ultrathin carbon support',16);}

function scene(o,r){const rid=r.record_id.replace('gerion-2001-',''),id=o.id;let art='',heading='',notes='';
 const flask=(x,y,options={})=>drawFlask(x,y,{...options,nitrogen:o.environment?.value==='Nitrogen'});
 if(rid==='silica-silanization'){
  if(id==='precipitate'){heading='Antisolvent precipitation';art=precipitateStock();notes='Retain the wet precipitate. The source does not specify the separation instrument or speed for this step.';}
  else if(id==='mps'){heading='MPS ligand priming';art=addition(['MPS','Vortex the wet precipitate'],{wet:true});notes='MPS is the trimethoxy reagent; the hydrolyzed drawing in Figure 1 illustrates its later surface chemistry.';}
  else if(id==='basify'){heading='Base-assisted clarification';art=addition(['TMAH in methanol','Add to clarify']);notes='The TMAH stock concentration is unreported; no commercial stock concentration is assumed.';}
  else if(id==='dilute'){heading='Dilution under nitrogen';art=flask(228,166)+panel(378,86,191,['Basified methanol','Three-neck flask']);notes='The reported vessel capacity is not the reaction-liquid volume. Numeric pressure and stirring speed are unreported.';}
  else if(/^stir[123]$/.test(id)){heading='Stirred siloxane processing';art=flask(230,168,{stir:true,layer:id==='stir1'?1:2});notes='The displayed stage controls its own duration. Stirring speed and exact surface structure are unreported.';}
  else if(/^heat[123]$/.test(id)){heading=id==='heat3'?'Post-quench thermal treatment':'Thermal consolidation';art=flask(230,144,{heated:true,stir:false,layer:id==='heat1'?1:2});notes='The source reports temperature and time, but does not name an oil bath, heating mantle or hot plate. Surface inset is conceptual.';}
  else if(/^cool[12]$/.test(id)){heading='Cooling';art=flask(220,165)+arrow(459,137,90)+text(459,213,'Cool',18);notes=id==='cool1'?'Room temperature is reported without a numeric value. No cooling bath or rate is specified.':'The reported cooling endpoint precedes quench addition. Do not carry the preceding heating temperature into this step.';}
  else if(id==='feed2'){heading='Secondary surface functionalization';art=flask(201,164,{layer:2})+panel(365,53,218,['Methanol + water','Phosphonate stock + MPS']);notes='The named phosphonate and its printed structure are inconsistent; preserve the ambiguity. The water fraction of this feed is not the whole-batch fraction.';}
  else if(id==='prepare-quench'){heading='Quench-mixture preparation';art=stockPreparation(['Methanol + TMSCl','TMAH pentahydrate']);notes='This is a separately prepared mixture. Pentahydrate mass is not the earlier methanolic TMAH stock volume.';}
  else if(id==='quench'){heading='Siloxane-growth quenching';art=flask(218,166,{layer:2})+panel(365,54,211,['Prepared quench','mixture'])+arrow(324,134,150);notes='Addition quenches reactive silanol sites; no instantaneous cooling, new uniform shell or measured atomic geometry is implied.';}
  else if(id==='rotovap'){heading='Rotary evaporation';art=`<g transform="translate(208 143) rotate(26)">${path('M-16 -54H16V-8C72 5 68 86 0 86C-68 86 -72 5 -16 -8Z')}${path('M-44 53Q0 68 44 53',C.green,6)}</g>`+path('M232 94L326 54H475V132')+box(450,132,53,66)+text(440,227,'Condensed solvent',15)+text(166,287,'Concentrated dispersion',17);notes='Reported volume-reduction factor is preserved. Vacuum, rotation speed and bath temperature are unreported; the discussion gives a differing limit.';}
  else if(/^rest/.test(id)||id==='age'){heading=id==='age'?'Post-quench aging':'Equilibration';art=id==='age'?flask(239,164,{stir:true}):labeled(232,183,'Resting dispersion');art+=panel(383,113,186,[id==='age'?'Under nitrogen':'Reported rest stage','Duration alongside']);notes='The source assigns distinct rest periods to different sample states. Do not collapse them into one hold or reuse earlier heating conditions.';}
  else if(/dialysis|dialyze/.test(id)){heading='Dialysis';art=dialysis(id==='dialyze-methanol'?'Methanol':'Millipore water');notes=id==='optional-dialysis'?'Optional water branch. Membrane MWCO is not an atomic or particle diameter.':'Retain the contents of the dialysis membrane; external methanol receives permeating small species.';}
  else if(/filter/.test(id)){heading='Membrane filtration';art=filter(o);notes=id==='optional-filter'?'The paper prints 0.22 mm at this step. The unit conflict remains explicit; it is not silently converted to µm.':'The source specifies the membrane and pore size. Retain the filtered dispersion; no unreported filter pressure is inferred.';}
  else if(id==='centrifugal-concentrate'){heading='Centrifugal membrane concentration';art=membraneConcentrate();notes='Retain the concentrate above the membrane. MWCO is distinct from centrifuge force; force and duration for this unit are unreported.';}
  else if(id==='column'){heading='Solvent exchange into phosphate buffer';art=column();notes='Use a NAP column or the separately described homemade Sephadex G-25 alternative. Only the fluorescent fraction is retained.';}
  else if(id==='optional-vacufuge'){heading='Optional centrifugal evaporation';art=rotor().replace('Centrifugation','Centrifugal evaporation')+arrow(273,161)+labeled(423,181,'Concentrated dispersion');notes='Vacufuge evaporation follows the optional water branch. The desired final concentration and evaporation duration are unreported.';}
  else if(id==='clear'){heading='Final sediment removal';art=centrifuge(false);notes='Retain the supernatant and discard sediment. The standard and optional water-purified branches are alternatives feeding this clearing step.';}
  else if(id==='store'){heading='Aqueous storage';art=labeled(205,181,'Aqueous nanocrystals')+panel(359,104,206,['Stored in air','OD range alongside']);notes='Particle concentration is an estimate using the reported assumed extinction coefficient, not a direct particle count.';}
 }
 else if(rid==='mpa-exchange'){
  heading='MPA surface exchange';
  if(id==='precipitate'){art=precipitateStock();notes='The initial precipitation has no specified centrifuge settings. This wet state precedes DMF/MPA addition.';}
  else if(id==='resuspend'){art=addition(['DMF + MPA','Resuspend wet precipitate'],{wet:true});notes='This ligand-exchange route is distinct from siloxane growth; no silica coating is implied.';}
  else if(id==='sonicate'){heading='Vortexing and sonication';art=box(70,117,246,175)+labeled(191,153,'Specimen')+path('M83 257Q109 234 135 257T187 257T239 257T291 257',C.green,2)+panel(369,116,199,['Vortex and sonicate','Until transparent']);notes='Sonicator geometry is schematic. Power, frequency and exact device type are unreported.';}
  else if(id==='age'){heading='Room-temperature aging';art=labeled(224,183,'MPA dispersion')+panel(371,112,197,['Room temperature','Reported aging period']);notes='No numeric room temperature or atmosphere is specified for this aging step.';}
  else if(id==='prepare-dmap'){heading='DMAP stock preparation';art=stockPreparation(['DMAP solute','DMF solvent']);notes='Reported mass is per unit stock volume. It is not the total DMAP mass used in the following variable-volume addition.';}
  else if(id==='add-dmap'){heading='DMAP-induced precipitation';art=addition(['Prepared DMAP/DMF stock','Cloudy dispersion']);notes='The stock volume is a reported range. Cloudiness is a qualitative endpoint, not a measured conversion.';}
  else if(id==='collect'){heading='Collect MPA-coated precipitate';art=centrifuge(true);notes='Retain the sediment here and discard supernatant. The final aqueous clearing later retains the opposite fraction.';}
  else if(id==='dry'){heading='Nitrogen drying';art=labeled(225,188,'Dry precipitate',{pellet:true,dry:true})+text(408,97,'N₂ flow',18)+arrow(345,139,155);notes='The MPA route explicitly dries the precipitate under nitrogen before aqueous redispersion; no drying time is reported.';}
  else if(id==='dissolve'){heading='Aqueous redispersion';art=aqueousDissolve();notes='Water volume is source reported. Do not import the siloxane route’s phosphate-buffer composition.';}
  else if(id==='clear'){heading='Aqueous clearing';art=centrifuge(false);notes='Retain the aqueous supernatant and discard sediment. This differs from the earlier pellet-collection step.';}
  else if(id==='optional-nap'){heading='Optional removal of excess MPA';art=column(true);notes='Optional NAP cleanup follows aqueous clearing; column passage count and exact volumes are unreported.';}
 }
 else if(rid==='core-shell-stock'){heading='Upstream core/shell stock';art=labeled(198,180,'CdSe/ZnS stock')+panel(350,105,228,['Butanol / TOPO','Aged at room temperature']);notes='Core and shell synthesis are cited upstream, not reproduced here. The butanol isomer is unspecified.';}
 else if(rid==='aps-functionalization'){heading='Optional amine functionalization';art=addition(['APS after MPS priming','With the phosphonate feed']);notes='APS dose is unreported. APS is an optional later addition, not a substitute for MPS in the initial priming step.';}
 else if(rid==='buffer-exchange'){heading='Alternative buffer-exchange routes';art=panel(39,97,235,['Water-soluble particles','Choose one alternative'])+arrow(306,158)+panel(365,68,202,['NAP size exclusion','OR dialysis','OR buffer addition']);notes='These are alternatives, not three sequential mandatory treatments. Transfer applies to both water-soluble coating families.';}
 else if(rid==='hplc-purification'){heading='Additional siloxane-complex cleanup';art=id==='dialyze'?dialysis('Medium unreported'):column(true);notes='This is the Figure 6 purification comparison, not an invented standard number of passes. Dialysis duration and NAP10 pass count are unreported.';}
 else if(rid==='afm-acquisition'){heading=id==='incubate'?'Incubation on mica':'Atomic force microscopy';art=mica(id);if(id==='incubate')art=path('M145 223L343 183L457 229L258 273Z')+text(300,127,'Leave the deposited specimen on mica',19)+text(300,305,'Incubation before rinsing',17);notes=id==='image'?'Particle heights and population-selection caveats remain separate from a measured atomic crystal structure.':'Mica preparation and specimen handling are distinct stages. No droplet shape or particle arrangement represents measured data.';}
 else if(rid==='tem-acquisition'||rid==='eels-acquisition'){heading=rid==='tem-acquisition'?'Transmission electron microscopy':'Electron energy-loss spectroscopy';art=id==='deposit'?grid(rid==='eels-acquisition'):id==='dry'?dryGrid(rid==='eels-acquisition'):electronMicroscopy(rid==='eels-acquisition');notes=rid==='tem-acquisition'?'The grid backing metal is unreported. Actual HRTEM micrographs are announced in the unlocated SI; the main article shows size distributions.':'The Si and Se edges are reported as preliminary observations; no EELS spectrum is supplied or recreated.';}
 else if(rid==='gel-salt-stability'&&id==='incubate'){heading='Separate salt-challenge incubations';art=saltIncubation();notes='Silica and MPA specimens are separate, as are the salt concentrations. The source’s figure-only extra salt lane remains identified alongside.';}
 else if(rid.startsWith('gel-')){heading='Agarose gel analysis';art=gel(o,r);notes='';}
 else if(rid==='hplc-acquisition'){heading=id==='inspect-fractions'?'Collection and fluorescence inspection':'Size-exclusion chromatography';art=hplcStage(id);notes='The paper’s blue and red chromatogram traces identify preparations, not emission colors. No synthetic chromatogram is drawn.';}
 else if(rid==='ellman-assay'){heading='Accessible-thiol assay';art=ellmanStage(id);notes='Paired-background subtraction gives an upper estimate confounded by free siloxane complexes and particle-concentration uncertainty.';}
 else if(rid==='optical-acquisition'){heading='Optical characterization';art=optical(id==='absorbance'?'UV–visible absorption':id==='emission'?'Fluorescence':'Relative quantum yield',id==='qy');notes=id==='qy'?'Matched optical density is at the stated excitation wavelength. Rhodamine 6G is a separate aqueous reference, not a synthesis reagent.':'Use original spectra and sample-specific assignments. No computed illustrative spectrum is presented as an experimental observation.';}
 else if(rid==='cw-photostability'){heading='Continuous-illumination stability';art=optical(id==='irradiate'?'Continuous laser':id==='record'?'Image time series':'Matched-OD specimens',id==='prepare');notes='The methods report a four-hour observation; the original figure axis covers 0–4000 s. A schematic is not the measured decay curve.';}
 else if(rid==='storage-photostability'){heading='Storage photoluminescence stability';art=id==='prepare'?stockPreparation(['Nanocrystal aliquot','Phosphate buffer']):optical('Integrated emission');notes='Normalize to each specimen’s day-1 signal. Storage monitoring is distinct from continuous laser irradiation.';}
 if(!art)return null;return {kind:rid+'-'+id,body:title(heading)+art+(notes?note(notes):'')};
}
export function buildGerion2001Scene(o,r){if(!r?.sources?.some(s=>s.doi==='10.1021/jp0105488')||!r.record_id.startsWith('gerion-2001-'))return null;const s=scene(o,r);if(!s)return null;return {kind:s.kind,svg:`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 415" role="img" aria-label="${esc(o.label)} — explanatory apparatus" style="width:100%;height:auto;fill:${C.ink}"><title>${esc(o.label)}</title><desc>Source-specific process illustration. Apparatus geometry and fluid colors are explanatory; conditions and evidence appear alongside. No measured microscopic structure or signal is simulated.</desc>${s.body}</svg>`,caption:'Stage-specific scientific illustration. Read the selected operation’s reported conditions, sample state and retained fraction alongside; apparatus geometry and colors are explanatory.'};}
export function createGerion2001Art(o,r){const s=buildGerion2001Scene(o,r);if(!s)return null;const d=document.createElement('div');d.className='protocol-art protocol-art-gerion2001';d.dataset.scene='gerion2001-'+s.kind;d.style.height='auto';d.innerHTML=s.svg;return d;}
